function can(k){return S.me&&S.me.role=='system_admin'||(S.perms||[]).indexOf(k)>=0}
function canAny(a){return a.some(can)}
function effPerms(p){if(!p)return [];if(p.role=='system_admin')return PALL.slice();return p.perms||(S.pdef&&S.pdef[p.role])||[]}
function pcan(p,k){return effPerms(p).indexOf(k)>=0}
function brList(){return pickBr()?S.branches:S.branches.filter(function(b){return b.id==S.me.branch_id})}
function staffList(b){return S.profiles.filter(function(p){return p.active&&(!b||!p.branch_id||p.branch_id==b||pcan(p,'all_branches'))})}
function pickBr(){return can('all_branches')||!S.me.branch_id}
function dname(p){var x=p&&p.full_name;return x&&!/@/.test(x)?x:'(بدون اسم)'}

/* ---------- boot / login ---------- */
async function boot(){
 if(!window.CFG||!CFG.url||!CFG.key){APP.innerHTML='<div class="card login"><h2>الإعداد ناقص</h2><p class="hint">افتح ملف config.js وضع رابط مشروع Supabase والمفتاح العام (anon).</p></div>';return}
 var hs=new URLSearchParams((location.hash||'').replace(/^#/,'')),qs=new URLSearchParams(location.search),rec=hs.get('type')=='recovery'||qs.get('type')=='recovery',herr=hs.get('error_code')||qs.get('error_code');
 if(!sb){sb=supabase.createClient(CFG.url,CFG.key);sb.auth.onAuthStateChange(function(ev){if(ev=='PASSWORD_RECOVERY')setTimeout(recoverView,0);if(ev=='SIGNED_OUT'&&S.me&&!S.idleOut){S.me=null;try{clearInterval(S.pt);clearInterval(S.idleT)}catch(e){}setTimeout(function(){loginView('انتهت جلستك، ادخل تاني.')},0)}})}
 var s=await sb.auth.getSession();
 if(herr){history.replaceState(null,'',location.pathname);if(!s.data.session)return loginView(herr=='otp_expired'?'لينك تغيير كلمة السر انتهت صلاحيته أو اتستخدم قبل كده. اطلب لينك جديد من «نسيت كلمة السر؟».':'اللينك غير صالح. اطلب لينك جديد.')}
 if(rec&&s.data.session)return recoverView();
 if(!s.data.session)return loginView();
 if(!(await mfaGate()))return;
 var p=await sb.from('profiles').select('*').eq('id',s.data.session.user.id).single();
 if(p.error||!p.data)return loginView('تعذر قراءة حسابك');
 S.me=p.data;
 if(!S.me.active){APP.innerHTML='<div class="card login"><h2>حسابك غير مفعّل</h2><p class="hint">اطلب من مدير النظام تفعيل حسابك وتحديد فرعك ودورك.</p><button class="btn" id="lo">خروج</button></div>';$('#lo').onclick=out;return}
 var r=await Promise.all([sb.from('zones').select('*').order('name'),sb.from('branches').select('*').order('name'),sb.from('products').select('*').order('name')]);
 S.zones=r[0].data||[];S.branchesAll=r[1].data||[];S.branches=S.branchesAll.filter(function(b){return !b.is_hq});S.products=r[2].data||[];
 await loadMe(p.data);
 shell();go(S.nav[0]);live();twCheck();idleStart();
 if(S._fresh){S._fresh=0;try{sb.rpc('login_ok',{p_ua:uaStr()}).then(function(){},function(){})}catch(e){}}
}
async function twCheck(){try{await sb.rpc('issue_task_warnings');var w=(await sb.from('task_warnings').select('day,score').eq('user_id',S.me.id).is('seen_at',null)).data||[];if(w.length)setTimeout(function(){msg('تحذير: تقييم مهامك كان أقل من '+TSK_MIN+'% في '+w.length+' يوم. افتح «المهام» للتفاصيل.',1)},1500)}catch(e){}}
async function loadMe(me){
 var r=await Promise.all([sb.rpc('my_perms'),sb.rpc('perm_defaults'),sb.from('profiles').select('id,full_name,role,branch_id,active,perms')]);
 S.me=me;S.me.full_name=dname(me);S.perms=r[0].data||[];S.pdef=r[1].data||{};
 S.profiles=(r[2].data||[]).map(function(x){x.full_name=dname(x);return x});
 S.sig=[S.me.role,S.me.branch_id,S.me.full_name,S.me.active,S.perms.slice().sort().join(',')].join('|')
}
async function refreshMe(){
 if(!S.me||!sb)return;var p=await sb.from('profiles').select('*').eq('id',S.me.id).single();if(p.error||!p.data)return;
 if(!p.data.active)return boot();
 var old=S.sig;await loadMe(p.data);
 if(old!==S.sig){var cur=S.cur;shell();go(S.nav.indexOf(cur)>=0?cur:S.nav[0]);msg('تم تحديث صلاحياتك')}
}
function live(){
 try{if(S.ch)sb.removeChannel(S.ch);S.ch=sb.channel('me-'+S.me.id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'profiles',filter:'id=eq.'+S.me.id},function(){refreshMe()}).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'user_id=eq.'+S.me.id},function(p){NT.last=p.new&&p.new.created_at||NT.last;ntNew(p.new)}).subscribe();ntPoll();setTimeout(pushBar,1500)}catch(e){}
 clearInterval(S.pt);S.pt=setInterval(function(){refreshMe();ntLoad()},60000);
 if(!live.b){live.b=1;document.addEventListener('visibilitychange',async function(){if(document.hidden||!S.me)return;if(!(await sessOk())){S.me=null;return loginView('انتهت جلستك، ادخل تاني.')}refreshMe()})}
}
