function mkText(o){return mkTpl(o.stage).replace(/\{الاسم\}/g,o.name||'').replace(/\{الفرع\}/g,o.branch||'شركة الأنوار').replace(/\{نهاية العرض\}/g,o.end||'')}
function mkUrl(o){var ph=waPhone(o.phone);return ph?'https://wa.me/'+ph+'?text='+encodeURIComponent(mkText(o)):''}
function mkBtn(o){if(!o.consent)return '<span class="btn sm wa off" title="العميل مش موافق على الرسائل التسويقية">'+WA_ICO+'</span>';var u=mkUrl(o),sent=MK_SENT[o.stage+'|'+o.k];
 return u?'<a class="btn sm wa'+(sent?' sent':'')+'" href="'+esc(u)+'" target="_blank" rel="noopener" data-mkk="'+esc(o.k)+'" data-mks="'+o.stage+'" title="'+esc((MK_T.filter(function(x){return x.k==o.stage})[0]||{}).t||'')+'">'+WA_ICO+(sent?' اتبعت':' واتساب')+'</a>':'<span class="btn sm wa off" title="رقم الهاتف غير صحيح">'+WA_ICO+'</span>'}
