var WA_FINE=10;
function waTier(o){if(o.kind=='paid')return 'paid';if(o.legal)return 't3';var d=+o.days||0;return d<=0?'t0':d<=30?'t1':d<=60?'t2':'t3'}
function waTpl(k){var t=WA_T.filter(function(x){return x.k==k})[0]||WA_T[1];try{return localStorage.getItem('waTpl2_'+k)||t.d}catch(e){return t.d}}
function waPhone(p){p=cuDig(p).replace(/[^0-9]/g,'');if(/^01[0-9]{9}$/.test(p))return '2'+p;if(/^1[0-9]{9}$/.test(p))return '20'+p;if(/^201[0-9]{9}$/.test(p))return p;if(/^00201[0-9]{9}$/.test(p))return p.slice(2);return ''}
function waText(o){var d=Math.max(0,+o.days||0);return waTpl(waTier(o)).replace(/\{الاسم\}/g,o.name||'').replace(/\{المبلغ\}/g,n(o.amount)).replace(/\{التاريخ\}/g,o.date||'').replace(/\{الفرع\}/g,o.branch||'').replace(/\{الكود\}/g,o.code||'').replace(/\{الأيام\}/g,d).replace(/\{الغرامة\}/g,n(d*WA_FINE)).replace(/\{القسط\}/g,n(o.inst||o.amount)).replace(/\{الأقساط\}/g,waCnt(o.cnt)).replace(/\{الإجمالي\}/g,n((+o.amount||0)+d*WA_FINE))}
function waUrl(o){var ph=waPhone(o.phone);return ph?'https://wa.me/'+ph+'?text='+encodeURIComponent(waText(o)):''}
function waSent(k){try{var d=JSON.parse(localStorage.getItem('waSent')||'{}');return d[k]==today}catch(e){return false}}
function waMark(k){try{var d=JSON.parse(localStorage.getItem('waSent')||'{}');Object.keys(d).forEach(function(x){if(d[x]!=today)delete d[x]});d[k]=today;localStorage.setItem('waSent',JSON.stringify(d))}catch(e){}}
function waBtn(o){var u=waUrl(o);return u?'<a class="btn wa'+(waSent(o.k)?' sent':'')+'" href="'+esc(u)+'" target="_blank" rel="noopener" data-wak="'+esc(o.k)+'" title="'+esc((WA_T.filter(function(x){return x.k==waTier(o)})[0]||{}).t||'واتساب')+'">'+WA_ICO+(waSent(o.k)?' اتبعت':' واتساب')+'</a>':'<span class="btn wa off" title="رقم الهاتف غير صحيح">'+WA_ICO+' مفيش رقم</span>'}
