function cuDig(s){return String(s==null?'':s).replace(/[٠-٩]/g,function(d){return '٠١٢٣٤٥٦٧٨٩'.indexOf(d)}).replace(/[۰-۹]/g,function(d){return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)})}
function cuNorm(s){return String(s==null?'':s).replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/\s+/g,' ').trim()}
function cuWords(s){return String(s||'').trim().split(/\s+/).filter(Boolean).length}
function cuQ(v){v=v==null?'':String(v);return /[",\n\t]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function cuParse(text){
 text=String(text||'').replace(/^﻿/,'');
 var lines=text.split(/\r?\n/),first=lines.filter(function(l){return l.trim()&&l.trim().charAt(0)!='#'})[0]||'';
 var d=first.indexOf('\t')>=0?'\t':first.indexOf(';')>=0&&first.indexOf(',')<0?';':',';
 var rows=[],row=[],cur='',q=false,i,c;
 for(i=0;i<text.length;i++){c=text.charAt(i);
  if(q){if(c=='"'){if(text.charAt(i+1)=='"'){cur+='"';i++}else q=false}else cur+=c}
  else if(c=='"')q=true;
  else if(c==d){row.push(cur);cur=''}
  else if(c=='\n'||c=='\r'){if(c=='\r'&&text.charAt(i+1)=='\n')i++;row.push(cur);cur='';rows.push(row);row=[]}
  else cur+=c}
 if(cur!==''||row.length){row.push(cur);rows.push(row)}
 return rows.filter(function(r){var a=String(r[0]||'').trim();return r.some(function(x){return String(x).trim()})&&a.charAt(0)!='#'&&a.indexOf('مثال')!==0})
}
function cuCheck(o,isNew){var e=[];
 if(cuWords(o.full_name)<4)e.push('الاسم أقل من 4 كلمات');
 if(o.phone&&!/^[0-9]{1,11}$/.test(o.phone))e.push('الهاتف أكثر من 11 رقمًا أو به حروف');
 if(o.national_id&&!/^[0-9]{1,14}$/.test(o.national_id))e.push('الرقم القومي أكثر من 14 رقمًا أو به حروف');
 if(o.customer_code&&o.customer_code.length>40)e.push('الكود طويل');
 return e}
