function curMonth(){return today.slice(0,7)}
function chk(r){if(r.error)throw r.error;return r.data||[]}
function dl(name,text){if(!DL_FREE.test(name)){if(!canExport(name))return;logExport(name,String(text).split('\n').length-1)}var b=new Blob(['﻿'+text],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();a.remove()}
