var TSK_MIN=80;
function ldate(ts){if(!ts)return null;var d=new Date(ts);return new Date(d.getTime()-d.getTimezoneOffset()*6e4).toISOString().slice(0,10)}
function tDay(t){return t.due_date||ldate(t.created_at)}
