function tbRange(P){if(P.per=='day')return [P.d,P.d];if(P.per=='month'){var y=+P.m.slice(0,4),mo=+P.m.slice(5,7),last=new Date(Date.UTC(y,mo,0)).getUTCDate();return [P.m+'-01',P.m+'-'+(last<10?'0':'')+last]}return [P.y+'-01-01',P.y+'-12-31']}
