async function aiChat(){var w=$('#aiv');
 if(!S.aiMsgs){S.aiMsgs=[];try{var r=await sb.from('ai_chats').select('*').eq('user_id',S.me.id).order('updated_at',{ascending:false}).limit(1);var c=(r.data||[])[0];if(c){S.aiChatId=c.id;S.aiMsgs=c.messages||[]}}catch(e){}}
 var sug=AI_SUG[S.me.role]||AI_SUG.sales;
 w.innerHTML='<div class="card"><div class="row"><h2>مساعد الأنوار</h2><button class="btn sm" id="aiclr">محادثة جديدة</button></div><p class="hint">اسأله عن شغلك بالعامية: يحلل أرقامك، يرتبلك أولوياتك، ويجهزلك مهام ورسايل. أي تنفيذ بيظهرلك تأكده الأول. وبيشوف بس اللي صلاحياتك تسمح بيه.</p><div class="aim" id="aim"></div><div class="pay" style="flex-wrap:wrap">'+sug.map(function(s){return '<button class="btn sm" data-aisg="'+esc(s)+'">'+esc(s)+'</button>'}).join('')+'</div><div style="display:flex;gap:8px;margin-top:8px"><textarea id="aiq" rows="2" placeholder="اكتب سؤالك…" style="flex:1"></textarea><button class="btn am" id="aisend">إرسال</button></div></div>';
 function draw(){var box=$('#aim');box.innerHTML=S.aiMsgs.length?S.aiMsgs.map(function(m,i){return '<div class="aib '+(m.role=='user'?'u':'a')+'">'+(m.role=='user'?esc(m.content).replace(/\n/g,'<br>'):mdLite(m.content))+(m.actions&&m.actions.length?m.actions.map(function(a,j){return aiActCard(a,i,j)}).join(''):'')+'</div>'}).join(''):'<p class="hint">ابدأ بسؤال أو اختار من الاقتراحات تحت.</p>';box.scrollTop=box.scrollHeight}
 async function save(){try{var clean=S.aiMsgs.slice(-40);if(S.aiChatId)await sb.from('ai_chats').update({messages:clean,updated_at:new Date().toISOString()}).eq('id',S.aiChatId);else{var x=await sb.from('ai_chats').insert({tenant_id:S.me.tenant_id,user_id:S.me.id,messages:clean}).select('id').single();if(x.data)S.aiChatId=x.data.id}}catch(e){}}
 async function send(q){q=(q||'').trim();if(!q)return;S.aiMsgs.push({role:'user',content:q});S.aiMsgs.push({role:'assistant',content:'… بيفكر'});draw();$('#aiq').value='';$('#aisend').disabled=true;
  var x=await sb.functions.invoke('ai-assistant',{body:{messages:S.aiMsgs.slice(0,-1).map(function(m){return {role:m.role,content:m.content}})}}),er=await fnErr(x),d=x.data||{};$('#aisend').disabled=false;S.aiMsgs.pop();
  if(er||d.error){S.aiMsgs.push({role:'assistant',content:'حصلت مشكلة: '+(er||d.error)})}
  else if(d.setup){S.aiMsgs.push({role:'assistant',content:d.reply+(S.me.role=='system_admin'?'\n\nلحد ما يتربط، تقدر تستخدم «تحليل الأداء وخطط العلاج» و«خطط التحسين» — شغالين من غير OpenAI.':'')});}
  else S.aiMsgs.push({role:'assistant',content:d.reply,actions:d.actions||[]});
  draw();save()}
 draw();
 $('#aisend').onclick=function(){send($('#aiq').value)};$('#aiq').onkeydown=function(e){if(e.key=='Enter'&&!e.shiftKey){e.preventDefault();send($('#aiq').value)}};
 $('#aiclr').onclick=function(){S.aiMsgs=[];S.aiChatId=null;draw()};
 w.onclick=async function(e){var t=e.target.closest('button,a');if(!t)return;var a;if((a=t.getAttribute('data-aisg')))return send(a);
  if((a=t.getAttribute('data-aiok'))){var p=a.split(':'),m=S.aiMsgs[+p[0]],act=m&&m.actions&&m.actions[+p[1]];if(!act||act.done)return;t.disabled=true;var ok=await aiDo(act);t.disabled=false;if(ok){act.done=1;draw();save()}}
  if((a=t.getAttribute('data-ainx'))){var p2=a.split(':'),m2=S.aiMsgs[+p2[0]];m2.actions[+p2[1]].done=2;draw();save()}}}
function aiActCard(a,i,j){var t={task:'مهمة',followup:'متابعة عميل منتهي',lead:'تحديث عميل محتمل',whatsapp:'رسالة واتساب'}[a.type]||a.type,body='';
 if(a.type=='task')body='<b>'+esc(a.title)+'</b>'+(a.details?'<div>'+esc(a.details)+'</div>':'')+'<div class="hint">لـ '+esc(a.assignee_id?un(a.assignee_id):'أنا')+(a.due_date?' · '+fd(a.due_date):'')+'</div>';
 else if(a.type=='followup')body=(a.status?'الحالة: '+esc(RFS[a.status]||a.status)+' · ':'')+esc(a.note||'');
 else if(a.type=='lead')body=(a.status?'الحالة: '+esc(a.status)+' · ':'')+esc(a.note||'')+(a.next_followup?' · متابعة '+fd(a.next_followup):'');
 else if(a.type=='whatsapp')body='<div style="white-space:pre-line">'+esc(a.message)+'</div>';
 return '<div class="aact"><div class="hint">مقترح: '+t+'</div>'+body+'<div class="pay" style="margin-top:6px">'+(a.done==1?tg('اتنفذ ✓','t0'):a.done==2?tg('اتلغى',''):'<button class="btn sm am" data-aiok="'+i+':'+j+'">'+(a.type=='whatsapp'?'افتح الواتساب':'تأكيد وتنفيذ')+'</button><button class="btn sm" data-ainx="'+i+':'+j+'">تجاهل</button>')+'</div></div>'}
async function aiDo(a){var x;
 if(a.type=='task'){x=await sb.from('tasks').insert({tenant_id:S.me.tenant_id,title:String(a.title).slice(0,200),details:a.details||null,assigned_to:a.assignee_id||S.me.id,due_date:a.due_date||today,status:'open',source:'ai',created_by:S.me.id,branch_id:S.me.branch_id||null});if(x.error){msg(em(x.error),1);return false}msg('اتعملت المهمة');return true}
 if(a.type=='followup'){var f=(await sb.from('renew_followups').select('notes,contact_count,status').eq('id',a.followup_id).single()).data;if(!f){msg('المتابعة مش موجودة أو مش متاحة لك',1);return false}
  x=await sb.from('renew_followups').update({status:a.status||(f.status=='new'?'contacted':f.status),notes:((f.notes?f.notes+'\n':'')+today+' — '+(a.note||'')).slice(-4000),last_contact_at:new Date().toISOString(),contact_count:(f.contact_count||0)+1}).eq('id',a.followup_id);if(x.error){msg(em(x.error),1);return false}msg('اتسجلت المتابعة');return true}
 if(a.type=='lead'){var o={};if(a.status)o.status=a.status;if(a.next_followup)o.next_followup=a.next_followup;if(a.note){var l=(await sb.from('leads').select('notes,contact_count').eq('id',a.lead_id).single()).data||{};o.notes=((l.notes?l.notes+'\n':'')+today+' — '+a.note).slice(-4000);o.last_contact_at=new Date().toISOString();o.contact_count=(l.contact_count||0)+1}
  x=await sb.from('leads').update(o).eq('id',a.lead_id);if(x.error){msg(em(x.error),1);return false}msg('اتحدث العميل');return true}
 if(a.type=='whatsapp'){var ph=null;if(a.customer_id)ph=((await sb.from('customers').select('phone').eq('id',a.customer_id).single()).data||{}).phone;else if(a.lead_id)ph=((await sb.from('leads').select('phone').eq('id',a.lead_id).single()).data||{}).phone;var p=waPhone(ph);if(!p){msg('رقم العميل مش موجود أو مش صحيح',1);return false}window.open('https://wa.me/'+p+'?text='+encodeURIComponent(a.message),'_blank');return true}
 return false}
