/* الخروج التلقائي بعد مدة من غير استخدام */
function idleStart(){var mins=+((S.sec||{}).idle_min)||30;S.idleMs=mins*60000;S.lastAct=Date.now();
 if(!idleStart.b){idleStart.b=1;var bump=function(){var n=Date.now();if(n-S.lastAct>5000){S.lastAct=n;try{localStorage.setItem('alw_act',String(n))}catch(e){}}};
  ['mousemove','keydown','click','touchstart','scroll'].forEach(function(ev){document.addEventListener(ev,bump,{passive:true,capture:true})})}
 clearInterval(S.idleT);S.idleT=setInterval(async function(){if(!S.me)return;var ls=0;try{ls=+localStorage.getItem('alw_act')||0}catch(e){}var last=Math.max(S.lastAct,ls),left=S.idleMs-(Date.now()-last);
  if(left<=0){clearInterval(S.idleT);try{await sb.rpc('log_sec_event',{p_kind:'logout_idle',p_note:Math.round(S.idleMs/60000)+' دقيقة'})}catch(e){}S.idleOut=1;out()}
  else if(left<65000&&!S.idleWarn){S.idleWarn=1;msg('هيتعمل خروج تلقائي خلال دقيقة لعدم الاستخدام — حرّك الماوس أو المس الشاشة للاستمرار',1)}else if(left>=65000)S.idleWarn=0},15000)}
